/// behaviour.rs writers_edit_only_their_own_notes: writer2 may not update writer1's note.
#[test]
fn require_example_2() {
    let d: types::Draft = fixture_fx_draft_2();
    let action: types::Action = types::Action::Update;
    let resource: types::Resource =
        types::Resource::Object(types::ObjectTypeId("note".to_string()));
    let subject: types::Subject = types::Subject {
        old: Some(types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("slug".to_string()),
                    types::Value::Str("first".to_string()),
                ),
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        }),
        new: Some(types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("slug".to_string()),
                    types::Value::Str("first".to_string()),
                ),
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        }),
    };
    assert_eq!(
        require(& d, & action, & resource, & subject),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::Unauthorized, message :
        "User(PrincipalId(\"alpha:writer2\")) may not Update Object(ObjectTypeId(\"note\"))"
        .to_string(), evidence : vec![types::Check { rule : "policy:writers_edit_own"
        .to_string(), passed : false, detail :
        "(record.$created_by == principal) is false".to_string() }], missing : None })))
    );
}

