/// behaviour.rs a_rejection_explains_itself: ConstraintViolated.
#[test]
fn create_record_example_2() {
    let d: types::Draft = fixture_fx_draft_1();
    let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
    let fields: std::collections::BTreeMap<types::FieldId, types::Value> =
        std::collections::BTreeMap::from([
            (
                types::FieldId("slug".to_string()),
                types::Value::Str("long".to_string()),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("A title that is far too long to fit".to_string()),
            ),
        ]);
    assert_eq!(
        create_record(& d, & object, & fields),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::ConstraintViolated, message :
        "constraint:note.title_length: A title has at most 24 characters [(len(new.title) <= 24)]"
        .to_string(), evidence : vec![types::Check { rule : "default:note.status"
        .to_string(), passed : true, detail : "'draft'".to_string() }, types::Check {
        rule : "policy:writers_read_notes".to_string(), passed : true, detail :
        "Create on Object(ObjectTypeId(\"note\"))".to_string() }, types::Check { rule :
        "workflow:note_status:initial".to_string(), passed : true, detail :
        "starts in draft".to_string() }, types::Check { rule : "required:note.slug"
        .to_string(), passed : true, detail : "present".to_string() }, types::Check {
        rule : "type:note.slug".to_string(), passed : true, detail : "string".to_string()
        }, types::Check { rule : "unique:note.slug".to_string(), passed : true, detail :
        "no other record has this value".to_string() }, types::Check { rule :
        "required:note.status".to_string(), passed : true, detail : "present".to_string()
        }, types::Check { rule : "type:note.status".to_string(), passed : true, detail :
        "string".to_string() }, types::Check { rule : "required:note.title".to_string(),
        passed : true, detail : "present".to_string() }, types::Check { rule :
        "type:note.title".to_string(), passed : true, detail : "string".to_string() },
        types::Check { rule : "workflow_state:note_status".to_string(), passed : true,
        detail : "draft is a state".to_string() }, types::Check { rule :
        "constraint:note.title_length".to_string(), passed : false, detail :
        "A title has at most 24 characters [(len(new.title) <= 24)]".to_string() }],
        missing : None })))
    );
}

