/// behaviour.rs undeclared_status_changes_are_refused_from_every_state: the guard (has_role(editor)) refuses the writer who owns the note.
#[test]
fn workflow_step_example_4() {
    let d: types::Draft = {
        let mut fixture = fixture_fx_draft_4();
        fixture.ctx.correlation = "test-5005".to_string();
        fixture.ctx.now = crate::prelude::Timestamp(5005);
        fixture.evidence = vec![types::Check {
            rule: "policy:writers_edit_own".to_string(),
            passed: true,
            detail: "x".to_string(),
        }];
        fixture
    };
    let old: types::Record = types::Record {
        id: types::RecordId(1),
        object: types::ObjectTypeId("note".to_string()),
        version: 1,
        created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
        created_at: crate::prelude::Timestamp(5000),
        updated_at: crate::prelude::Timestamp(5000),
        fields: std::collections::BTreeMap::from([
            (
                types::FieldId("slug".to_string()),
                types::Value::Str("first".to_string()),
            ),
            (
                types::FieldId("status".to_string()),
                types::Value::Str("draft".to_string()),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("First".to_string()),
            ),
        ]),
    };
    let candidate: types::Record = types::Record {
        id: types::RecordId(1),
        object: types::ObjectTypeId("note".to_string()),
        version: 2,
        created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
        created_at: crate::prelude::Timestamp(5000),
        updated_at: crate::prelude::Timestamp(5005),
        fields: std::collections::BTreeMap::from([
            (
                types::FieldId("slug".to_string()),
                types::Value::Str("first".to_string()),
            ),
            (
                types::FieldId("status".to_string()),
                types::Value::Str("published".to_string()),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("First".to_string()),
            ),
        ]),
    };
    let workflow: types::WorkflowDef = fixture_fx_workflow_def_2();
    assert_eq!(
        workflow_step(&d, &old, &candidate, &workflow),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::WorkflowViolation,
                message: "publish: guard is not true".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:writers_edit_own".to_string(),
                        passed: true,
                        detail: "x".to_string()
                    },
                    types::Check {
                        rule: "workflow:note_status".to_string(),
                        passed: false,
                        detail: "publish: guard is not true".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

