/// When the snapshot does not cover the record the guard follows, the answer is InsufficientState naming it, not a refused transition.
#[test]
fn workflow_step_example_8() {
    let d: types::Draft = {
        let mut fixture = fixture_fx_draft_11();
        fixture.coverage = types::Coverage::Partial(std::collections::BTreeSet::new());
        fixture.tenant.records.insert(
            types::ObjectTypeId("person".to_string()),
            std::collections::BTreeMap::from([(
                types::RecordId(9),
                std::sync::Arc::new(types::Record {
                    id: types::RecordId(9),
                    object: types::ObjectTypeId("person".to_string()),
                    version: 1,
                    created_by: Some(types::PrincipalId("alpha:owner".to_string())),
                    created_at: crate::prelude::Timestamp(4000),
                    updated_at: crate::prelude::Timestamp(4000),
                    fields: std::collections::BTreeMap::from([(
                        types::FieldId("name".to_string()),
                        types::Value::Str("Ada".to_string()),
                    )]),
                }),
            )]),
        );
        fixture
    };
    let old: types::Record = fixture_fx_record_4();
    let candidate: types::Record = fixture_fx_record_5();
    let workflow: types::WorkflowDef = fixture_fx_workflow_def_3();
    assert_eq!(
        workflow_step(& d, & old, & candidate, & workflow),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::InsufficientState, message :
        "the snapshot does not cover Record { object: ObjectTypeId(\"person\"), id: RecordId(9) }"
        .to_string(), evidence : vec![types::Check { rule : "coverage".to_string(),
        passed : false, detail :
        "Record { object: ObjectTypeId(\"person\"), id: RecordId(9) }".to_string() }],
        missing : Some(types::Need::Record { object : types::ObjectTypeId("person"
        .to_string()), id : types::RecordId(9) }) })))
    );
}

