/// behaviour.rs writers_edit_only_their_own_notes; with a stale expected version too, the refusal is Unauthorized: authorisation comes before the version check.
#[test]
fn update_record_example_3() {
    let d: types::Draft = fixture_fx_draft_2();
    let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
    let id: types::RecordId = types::RecordId(1);
    let fields: std::collections::BTreeMap<types::FieldId, types::Value> =
        std::collections::BTreeMap::from([(
            types::FieldId("title".to_string()),
            types::Value::Str("Mine now".to_string()),
        )]);
    let expected_version: Option<u64> = Some(7);
    assert_eq!(
        update_record(& d, & object, & id, & fields, expected_version),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::Unauthorized, message :
        "User(PrincipalId(\"alpha:writer2\")) may not Update Object(ObjectTypeId(\"note\"))"
        .to_string(), evidence : vec![types::Check { rule : "policy:writers_edit_own"
        .to_string(), passed : false, detail :
        "(record.$created_by == principal) is false".to_string() }], missing : None })))
    );
}

/// behaviour.rs every_rejection_lists_at_least_one_failed_check: stale version.
#[test]
fn update_record_example_4() {
    let d: types::Draft = fixture_fx_draft_5();
    let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
    let id: types::RecordId = types::RecordId(1);
    let fields: std::collections::BTreeMap<types::FieldId, types::Value> =
        std::collections::BTreeMap::from([(
            types::FieldId("body".to_string()),
            types::Value::Str("two".to_string()),
        )]);
    let expected_version: Option<u64> = Some(7);
    assert_eq!(
        update_record(&d, &object, &id, &fields, expected_version),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::VersionConflict,
                message: "record is at version 1, expected 7".to_string(),
                evidence: vec![types::Check { rule : "policy:writers_edit_own"
        .to_string(), passed : true, detail :
        "Update on Object(ObjectTypeId(\"note\")) where (record.$created_by == principal)"
        .to_string() }, types::Check { rule : "intent:version_conflict".to_string(),
        passed : false, detail : "record is at version 1, expected 7".to_string() }],
                missing: None
            }
        )))
    );
}

/// behaviour.rs every_rejection_lists_at_least_one_failed_check: unknown record, for the editor, who may update any note and so learns that it is missing.
