/// Example 5 of `delete-record`.
#[test]
fn delete_record_example_5() {
    let d: types::Draft = fixture_fx_draft_12();
    let object: types::ObjectTypeId = types::ObjectTypeId("person".to_string());
    let id: types::RecordId = types::RecordId(1);
    let expected_version: Option<u64> = Some(3);
    assert_eq!(
        delete_record(&d, &object, &id, expected_version),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::VersionConflict,
                message: "record is at version 1, expected 3".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:editors_manage_people".to_string(),
                        passed: true,
                        detail: "Delete on Object(ObjectTypeId(\"person\"))".to_string()
                    },
                    types::Check {
                        rule: "intent:version_conflict".to_string(),
                        passed: false,
                        detail: "record is at version 1, expected 3".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

