/// behaviour.rs removing_the_last_role_asks_for_the_sessions_to_end_and_the_last_owner_stays: the last owner stays.
#[test]
fn change_member_example_4() {
    let d: types::Draft = fixture_fx_draft_13();
    let who: types::PrincipalId = types::PrincipalId("alpha:owner".to_string());
    let role: types::RoleId = types::RoleId("owner".to_string());
    let grant: bool = false;
    assert_eq!(
        change_member(&d, &who, &role, grant),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::InvalidIntent,
                message: "a tenant keeps at least one owner".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:builtin_owner".to_string(),
                        passed: true,
                        detail: "Manage on Members".to_string()
                    },
                    types::Check {
                        rule: "permission:confer:owner".to_string(),
                        passed: true,
                        detail: "an owner confers owner".to_string()
                    },
                    types::Check {
                        rule: "intent:invalid_intent".to_string(),
                        passed: false,
                        detail: "a tenant keeps at least one owner".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

